export interface TierStay {
  name: string
  image: string
  amenities: string[]
  // Prototype-matching lodge profile text shown on its Camps-tab card, below
  // the amenities. Optional — no existing lodge has this authored yet; the
  // card simply omits the paragraph until it does (no fabricated filler).
  description?: string
}

export interface ItineraryDay {
  day: number
  title: string
  description: string
  accommodation: string
  meals: string
  insiderFact?: string
  // "Location" column for the optional "Itinerary at a Glance" summary table —
  // the "Focus" column is just `title`, so no separate field is needed for that.
  location?: string
  // Prototype-matching "Morning Schedule" / "Afternoon & Sunset" breakdown,
  // shown under the day's description when authored. Optional — no existing
  // day has this content yet (only `description`, one paragraph per day);
  // left unset rather than split synthetically.
  morningActivity?: string
  afternoonActivity?: string
  // Per-day highlights (distinct from the package-level `highlights` field
  // on SafariPackage) -- e.g. "Cross-border private transfer" for this
  // specific day. Optional, same reasoning as morning/afternoonActivity.
  dayHighlights?: string[]
  accommodationByTier?: {
    trail?: TierStay
    reserve?: TierStay
    sovereign?: TierStay
  }
  // Separate two-tier variant for packages using Luxury/Ultra-Luxury naming
  // (e.g. the family safari line) instead of the Wilderness Trail/Reserve/
  // Sovereign vocabulary — kept independent rather than overloading
  // accommodationByTier with mismatched tier labels.
  accommodationByFamilyTier?: {
    luxury?: TierStay
    ultraLuxury?: TierStay
  }
}

export interface PricingTierRow {
  pax: number
  // Optional so existing single-season packages need no changes; a package
  // that wants a High/Low season toggle just tags every row with a season —
  // PriceTierSwitcher only renders the toggle when it sees more than one.
  season?: 'high' | 'low'
  // trail, reserve, and sovereign are all optional — a package supplies
  // whichever tiers it actually offers; PriceTierSwitcher only renders
  // buttons for tiers that are present.
  trail?: number
  reserve?: number
  sovereign?: number
}

export interface FamilyPricingRow {
  season: 'high' | 'low'
  familySize: number
  luxury: number
  ultraLuxury: number
}

export interface SafariPackage {
  slug: string
  name: string
  duration: number
  destinations: string[]
  // Replaced (not extended) the old 4-value union as part of the
  // SafariBookings-style rebuild — every package's value was remapped by
  // reading its actual content (see the migration/remap commit for the
  // reviewed old→new mapping), not mechanically renamed.
  type:
    | 'big_five_game_drives'
    | 'migration'
    | 'photographic'
    | 'walking'
    | 'cultural'
    | 'gorilla_trekking'
    | 'beach_extension'
    | 'mountain_trekking'
  priceFrom: number
  groupSize: { min: number; max: number }
  highlights: string[]
  itinerary: ItineraryDay[]
  included: string[]
  excluded: string[]
  heroImage: string
  // Descriptive alt text for heroImage — falls back to `name` if absent (kept
  // optional so this can land incrementally across the 44 packages rather
  // than requiring every package to be touched in the same pass).
  heroImageAlt?: string
  gallery: { src: string; alt: string }[]
  badge?: 'bestseller' | 'new' | 'popular'
  bestFor: string[]
  // Optional per-pax x tier pricing grid. Absent on most packages — the page
  // falls back to the flat `priceFrom` display when this isn't populated.
  pricingTiers?: PricingTierRow[]
  // Set when pricingTiers was derived from priceFrom via a markup formula
  // rather than confirmed real rates — the page shows a "confirm with our
  // team" note when true.
  pricingTiersProvisional?: boolean
  includedCategorized?: {
    transfers?: string[]
    accommodationMeals?: string[]
    guidingGameDrives?: string[]
  }
  excludedCategorized?: string[]
  notes?: string[]
  // Two-tier (Luxury / Ultra-Luxury) x season pricing grid, priced by family
  // size rather than raw pax count — used by the family safari package only.
  familyPricing?: FamilyPricingRow[]
  faq?: { q: string; a: string }[]
  // Intro paragraphs shown directly under the hero, above the quick-info row.
  overview?: string[]
  // The short "why book with us" one-liner shown as a quick-info chip.
  tagline?: string
  // The "Best time to travel" line shown as a quick-info chip.
  bestTimeToTravel?: string
  // "Why This Itinerary Is Different" section, rendered after Highlights.
  whyDifferent?: { heading: string; paragraphs: string[] }
  // "Destination Highlights" / "Photography Highlights" cards, rendered after whyDifferent.
  // `heading` carries the section's own title since docs vary it ("Destination Highlights",
  // "Photography Highlights", "Highlights") rather than assuming one fixed label.
  destinationHighlights?: { heading: string; items: { title: string; text: string }[] }
  // Overrides for the auto-generated <title>/<meta description> when a package
  // supplies its own SEO-authored copy instead of relying on the name/highlights fallback.
  metaTitle?: string
  metaDescription?: string
  // "Wildlife Radar" tab data — target species and their real sighting likelihood
  // on this specific itinerary/route, not a generic country-wide checklist.
  wildlifeTargets?: { name: string; chance: 'Guaranteed' | 'High' | 'Seasonal' | 'Rare'; note?: string }[]
  // Structured peak/shoulder/green season breakdown + a plain-language
  // recommendation — kept alongside bestTimeToTravel (that stays the short
  // quick-info chip string), not replacing it.
  seasonalityGuide?: {
    peakSeason?: string
    shoulderSeason?: string
    greenSeason?: string
    recommendation?: string
  }
  // Packing/travel advice shown in its own "Practical Tips" section.
  practicalTips?: string[]
  // Who's actually running this trip. Real, typed field — defaults to
  // 'EWA Safari Outfitters' for every package today (cosmetic until partner/
  // DMC listings exist), not a stub.
  operatorName?: string
  // Short month labels (e.g. ["Jun","Jul","Aug"]) for the listing page's
  // month-picker filter and the card's "best months" pill.
  bestMonths?: string[]
}

