      "Arusha National Park's guided walking safari — one of Tanzania's only parks offering this on foot, at an easy, unhurried pace",
      'A full day inside Ngorongoro Crater, roughly 260 km² (100 sq mi) of enclosed wildlife-rich caldera, reached by vehicle rather than any strenuous descent',
      'Three full nights in the Serengeti, giving the trip room to breathe rather than compressing the plains into a single day',
      'A flight back to Arusha instead of a long final drive — under an hour in the air, against what would otherwise be a six-hour-plus return journey',
